package com.bank.trailing;

import java.util.ArrayDeque;
import java.util.Deque;

// Maximum of each sliding window of size k using a monotonic deque.
public class RollingPeakFinder {

    public int[] maxOfEachWindow(int[] prices, int k) {
        if (prices.length == 0 || k <= 0) {
            return new int[0];
        }
        int n = prices.length;
        int[] result = new int[n - k + 1];
        Deque<Integer> deque = new ArrayDeque<>(); // indices, values decreasing

        for (int i = 0; i < n; i++) {
            // Drop smaller trailing indices: they can never be the max now.
            while (!deque.isEmpty() && prices[deque.peekLast()] <= prices[i]) {
                deque.pollLast();
            }
            deque.offerLast(i);

            // Drop the front if it has slid out of the window.
            if (deque.peekFirst() <= i - k) {
                deque.pollFirst();
            }

            // Once the first window is complete, record its maximum.
            if (i >= k - 1) {
                result[i - k + 1] = prices[deque.peekFirst()];
            }
        }
        return result;
    }
}
