package com.bank.trailing;

import java.util.Arrays;
import java.util.logging.Logger;

// Reports rolling peak prices used for trailing-stop alerts.
public class TrailingStopService {

    private static final Logger log = Logger.getLogger(TrailingStopService.class.getName());
    private final RollingPeakFinder finder;

    public TrailingStopService(RollingPeakFinder finder) {
        this.finder = finder;
    }

    public int[] rollingPeaks(int[] priceFeed, int windowSeconds) {
        int[] peaks = finder.maxOfEachWindow(priceFeed, windowSeconds);
        log.info(() -> "Feed " + Arrays.toString(priceFeed)
                + " rolling peaks (k=" + windowSeconds + ") = " + Arrays.toString(peaks));
        return peaks;
    }
}
