package com.bank.trailing;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class RollingPeakDemo {

    private static final Logger log = Logger.getLogger(RollingPeakDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) {
            root.removeHandler(h);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Rolling Peak for Trailing Stop");
        TrailingStopService service = new TrailingStopService(new RollingPeakFinder());

        int[] priceFeed = {1, 3, -1, -3, 5, 3, 6, 7};
        // window size 3 → peaks: [3, 3, 5, 5, 6, 7]
        service.rollingPeaks(priceFeed, 3);
    }
}
